-- Một dự án trong bảy để NULL cả hai: đội hai người và một repo là trạng thái có thật trên bảng dự án này, và nhánh "không có phần giới thiệu đội" phải có dữ liệu để chạy.

UPDATE socialapp.t_project_positions pos
   SET role_summary         = v.role_summary,
       responsibilities     = v.responsibilities::jsonb,
       requirements         = v.requirements::jsonb,
       nice_to_have         = v.nice_to_have::jsonb,
       min_years_experience = v.min_years,
       seniority_level      = v.seniority
  FROM (VALUES
    (1, 'Chịu trách nhiệm về chất lượng trước khi người dùng chịu: thiết kế bộ kiểm thử, tự động hoá phần lặp lại và giữ quy trình phát hành đáng tin.', '["Thiết kế ca kiểm thử theo phân vùng tương đương và giá trị biên","Tự động hoá phần kiểm thử hồi quy và giữ bộ test không nhiễu","Viết báo cáo lỗi tái hiện được, kèm bước và dữ liệu cụ thể"]'::jsonb, '["Đã viết kiểm thử tự động cho một sản phẩm chạy thật","Biết thiết kế ca kiểm thử có phương pháp, không chỉ bấm thử","Đọc được log và khoanh vùng lỗi trước khi báo"]'::jsonb, '["Có kinh nghiệm kiểm thử hiệu năng hoặc kiểm thử API"]'::jsonb, 2, 'MID'),
    (2, 'Đi hết một tính năng từ giao diện tới cơ sở dữ liệu, và chịu trách nhiệm cho nó sau khi lên môi trường thật chứ không dừng ở lúc gộp mã.', '["Hiện thực tính năng trọn vẹn: giao diện, API và lược đồ dữ liệu","Chia việc thành các lát cắt nhỏ đưa lên được sớm","Trực xử lý sự cố cho những tính năng mình đã đưa lên"]'::jsonb, '["Làm được cả hai phía và biết rõ mình yếu hơn ở phía nào","Đã đưa một tính năng ra người dùng thật từ đầu tới cuối","Thoải mái với việc ước lượng và cắt phạm vi khi cần"]'::jsonb, '["Có kinh nghiệm dựng quy trình tích hợp liên tục cho nhóm nhỏ"]'::jsonb, 5, 'SENIOR'),
    (3, 'Đi hết một tính năng từ giao diện tới cơ sở dữ liệu, và chịu trách nhiệm cho nó sau khi lên môi trường thật chứ không dừng ở lúc gộp mã.', '["Hiện thực tính năng trọn vẹn: giao diện, API và lược đồ dữ liệu","Chia việc thành các lát cắt nhỏ đưa lên được sớm","Trực xử lý sự cố cho những tính năng mình đã đưa lên"]'::jsonb, '["Làm được cả hai phía và biết rõ mình yếu hơn ở phía nào","Đã đưa một tính năng ra người dùng thật từ đầu tới cuối","Thoải mái với việc ước lượng và cắt phạm vi khi cần"]'::jsonb, '["Có kinh nghiệm dựng quy trình tích hợp liên tục cho nhóm nhỏ"]'::jsonb, NULL, NULL),
    (4, 'Chịu trách nhiệm về chất lượng trước khi người dùng chịu: thiết kế bộ kiểm thử, tự động hoá phần lặp lại và giữ quy trình phát hành đáng tin.', '["Thiết kế ca kiểm thử theo phân vùng tương đương và giá trị biên","Tự động hoá phần kiểm thử hồi quy và giữ bộ test không nhiễu","Viết báo cáo lỗi tái hiện được, kèm bước và dữ liệu cụ thể"]'::jsonb, '["Đã viết kiểm thử tự động cho một sản phẩm chạy thật","Biết thiết kế ca kiểm thử có phương pháp, không chỉ bấm thử","Đọc được log và khoanh vùng lỗi trước khi báo"]'::jsonb, '["Có kinh nghiệm kiểm thử hiệu năng hoặc kiểm thử API"]'::jsonb, 2, 'MID'),
