    (95, 'Giữ đường đi từ mã nguồn tới môi trường thật ngắn và an toàn: hạ tầng khai báo bằng mã, quy trình phát hành tự động và khả năng quan sát hệ thống.', '["Dựng và duy trì quy trình build, kiểm thử, phát hành tự động","Mô tả hạ tầng bằng mã, không cấu hình bằng tay trên máy chủ","Đặt cảnh báo dựa trên triệu chứng người dùng gặp, không dựa trên ngưỡng máy"]'::jsonb, '["Thạo Docker và ít nhất một nền tảng điều phối container","Đã dựng quy trình phát hành tự động cho một nhóm nhiều người","Viết được script tự động hoá và đọc được log hệ thống"]'::jsonb, '["Có kinh nghiệm tối ưu chi phí hạ tầng theo hoá đơn thật"]'::jsonb, 5, 'SENIOR'),
    (96, 'Dựng phần giao diện người dùng nhìn thấy và chạm vào: bố cục, trạng thái, hiệu năng tải trang và khả năng truy cập trên cả máy tính lẫn điện thoại.', '["Hiện thực giao diện từ thiết kế, chạy đúng trên nhiều kích thước màn hình","Tách phần dùng lại được thành component và giữ chúng có tài liệu","Đo và cải thiện thời gian tải trang cùng các chỉ số trải nghiệm"]'::jsonb, '["Thành thạo một framework component hiện đại và quản lý trạng thái","Đọc hiểu thiết kế và trao đổi trực tiếp với người thiết kế","Nắm cơ bản về khả năng truy cập: ngữ nghĩa HTML, tiêu điểm bàn phím"]'::jsonb, '["Từng làm việc với hệ thống design system dùng chung"]'::jsonb, NULL, NULL),
    (97, 'Phụ trách phần máy chủ của sản phẩm: thiết kế API, mô hình dữ liệu và các tác vụ chạy nền, từ lược đồ cơ sở dữ liệu cho tới lúc chạy thật.', '["Thiết kế và hiện thực API cho ứng dụng web và di động dùng chung","Viết migration và giữ lược đồ cơ sở dữ liệu khớp với mã nguồn","Theo dõi độ trễ, tỉ lệ lỗi và xử lý sự cố phần dịch vụ mình phụ trách"]'::jsonb, '["Đã từng xây dựng và vận hành ít nhất một dịch vụ REST chạy thật","Thạo SQL: biết đọc kế hoạch truy vấn và đặt index đúng chỗ","Viết được kiểm thử tự động cho phần mình làm"]'::jsonb, '["Có kinh nghiệm với hàng đợi việc nền hoặc kiến trúc hướng sự kiện"]'::jsonb, 2, 'MID'),
