    (131, 'Chịu trách nhiệm về chất lượng trước khi người dùng chịu: thiết kế bộ kiểm thử, tự động hoá phần lặp lại và giữ quy trình phát hành đáng tin.', '["Thiết kế ca kiểm thử theo phân vùng tương đương và giá trị biên","Tự động hoá phần kiểm thử hồi quy và giữ bộ test không nhiễu","Viết báo cáo lỗi tái hiện được, kèm bước và dữ liệu cụ thể"]'::jsonb, '["Đã viết kiểm thử tự động cho một sản phẩm chạy thật","Biết thiết kế ca kiểm thử có phương pháp, không chỉ bấm thử","Đọc được log và khoanh vùng lỗi trước khi báo"]'::jsonb, '["Có kinh nghiệm kiểm thử hiệu năng hoặc kiểm thử API"]'::jsonb, 5, 'SENIOR'),
    (132, 'Chịu trách nhiệm về chất lượng trước khi người dùng chịu: thiết kế bộ kiểm thử, tự động hoá phần lặp lại và giữ quy trình phát hành đáng tin.', '["Thiết kế ca kiểm thử theo phân vùng tương đương và giá trị biên","Tự động hoá phần kiểm thử hồi quy và giữ bộ test không nhiễu","Viết báo cáo lỗi tái hiện được, kèm bước và dữ liệu cụ thể"]'::jsonb, '["Đã viết kiểm thử tự động cho một sản phẩm chạy thật","Biết thiết kế ca kiểm thử có phương pháp, không chỉ bấm thử","Đọc được log và khoanh vùng lỗi trước khi báo"]'::jsonb, '["Có kinh nghiệm kiểm thử hiệu năng hoặc kiểm thử API"]'::jsonb, NULL, NULL),
    (133, 'Làm việc với dữ liệu của sản phẩm: đường ống xử lý, chất lượng dữ liệu và các mô hình chạy được trong môi trường thật chứ không chỉ trong notebook.', '["Xây dựng và duy trì đường ống dữ liệu chạy theo lịch","Kiểm tra chất lượng dữ liệu và cảnh báo khi số liệu lệch bất thường","Đưa mô hình ra môi trường thật và theo dõi kết quả sau đó"]'::jsonb, '["Thạo Python và SQL ở mức làm việc hằng ngày","Đã đưa ít nhất một mô hình hoặc đường ống dữ liệu vào chạy thật","Trình bày được kết quả cho người không làm kỹ thuật"]'::jsonb, '["Có kinh nghiệm với công cụ điều phối luồng dữ liệu"]'::jsonb, 2, 'MID'),
    (134, 'Phụ trách ứng dụng di động: vòng đời màn hình, chế độ ngoại tuyến, dung lượng gói cài đặt và quy trình phát hành lên hai kho ứng dụng.', '["Hiện thực màn hình và điều hướng theo chuẩn của từng nền tảng","Xử lý trạng thái ngoại tuyến và đồng bộ lại khi có mạng","Chuẩn bị bản phát hành, theo dõi sự cố và tỉ lệ lỗi sau khi phát hành"]'::jsonb, '["Đã phát hành ít nhất một ứng dụng lên App Store hoặc Google Play","Hiểu vòng đời màn hình và giới hạn tài nguyên trên thiết bị","Biết đọc báo cáo sự cố và lần ngược về nguyên nhân"]'::jsonb, '["Từng làm phần đẩy thông báo hoặc lưu trữ dữ liệu ngoại tuyến"]'::jsonb, 5, 'SENIOR'),
